import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.DJo0M80U.js";const v=JSON.parse('{"title":"Java 快速入门 02-当前实践说明","description":"记录 Java、Spring Boot、Maven、JUnit 的当前官方依据，并说明旧笔记在学习路线中的使用边界。","frontmatter":{"title":"Java 快速入门 02-当前实践说明","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring Boot","Maven","JUnit","最佳实践"],"sidebarWeight":4,"description":"记录 Java、Spring Boot、Maven、JUnit 的当前官方依据，并说明旧笔记在学习路线中的使用边界。","lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/02-当前实践说明.md","filePath":"posts/java快速入门/02-当前实践说明.md"}'),o={name:"posts/java快速入门/02-当前实践说明.md"};function i(l,t,n,h,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<div><h1 id="_02-当前实践说明" tabindex="-1">02-当前实践说明 <a class="header-anchor" href="#_02-当前实践说明" aria-label="Permalink to &quot;02-当前实践说明&quot;">​</a></h1><p>这套笔记来自长期积累，里面既有仍然有用的基础知识，也有带明显年代感的框架和工具。学习时先按本页的实践边界取舍，再进入具体文章。</p><h2 id="版本选择" tabindex="-1">版本选择 <a class="header-anchor" href="#版本选择" aria-label="Permalink to &quot;版本选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>当前建议</th><th>学习时怎么用</th></tr></thead><tbody><tr><td>Java</td><td>新机器优先装 Java 21 或 Java 25 这样的 LTS 版本；练习示例保持 Java 17+ 可运行</td><td>基础语法不追逐新特性，先保证能编译、能测试、能解释</td></tr><tr><td>Spring Boot</td><td>新项目至少按 Java 17+ 思考；具体版本跟公司或项目一致</td><td>旧文章可帮助理解概念，实际新项目优先看官方文档</td></tr><tr><td>Maven</td><td>用 <code>pom.xml</code> 管理构建、依赖、测试和打包</td><td>不只记命令，要能解释依赖从哪里来、生命周期跑了什么</td></tr><tr><td>JUnit</td><td>新练习使用 Jupiter 风格测试；项目版本跟 Spring Boot 依赖管理保持一致</td><td>每个阶段至少有一个可重复运行的测试或验收命令</td></tr></tbody></table><h2 id="官方来源记录" tabindex="-1">官方来源记录 <a class="header-anchor" href="#官方来源记录" aria-label="Permalink to &quot;官方来源记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>它说明了什么</th><th>本课程采用的取舍</th></tr></thead><tbody><tr><td><a href="https://www.oracle.com/java/technologies/java-se-support-roadmap.html" target="_blank" rel="noreferrer">Oracle Java SE Support Roadmap</a></td><td>Java 8、11、17、21、25 是 LTS 版本，后续 LTS 按路线继续发布</td><td>导读不再把 Java 8 当作唯一默认版本；新学习环境按 Java 17+，更推荐 LTS</td></tr><tr><td><a href="https://www.oracle.com/java/technologies/javase/25-relnote-issues.html" target="_blank" rel="noreferrer">Oracle Java 25 Release Notes</a></td><td>JDK 25 是 Java SE 25 平台的完整实现，并包含开发、调试、监控相关 API</td><td>课程不强迫使用 Java 25 新特性；只把它作为当前 LTS 选择之一</td></tr><tr><td><a href="https://docs.spring.io/spring-boot/system-requirements.html" target="_blank" rel="noreferrer">Spring Boot System Requirements</a></td><td>Spring Boot 当前文档要求 Java 17 或更高版本，并给出 Maven、Gradle 支持范围</td><td>Spring Boot 章节按 Java 17+ 作为底线，旧 Spring 文章用于理解，不作为新项目模板</td></tr><tr><td><a href="https://maven.apache.org/guides/getting-started/" target="_blank" rel="noreferrer">Apache Maven Getting Started Guide</a></td><td>Maven 通过统一项目结构和最佳实践管理构建、文档、依赖、发布等</td><td>Maven 章节要围绕 <code>pom.xml</code>、生命周期、依赖范围和可重复构建来学</td></tr><tr><td><a href="https://docs.junit.org/6.1.1/overview.html" target="_blank" rel="noreferrer">JUnit User Guide</a></td><td>JUnit Platform 是 JVM 测试框架基础，支持多种测试引擎和命令行运行</td><td>学习验收不只看页面能启动，还要保留测试输出和失败用例</td></tr></tbody></table><h2 id="旧材料的使用边界" tabindex="-1">旧材料的使用边界 <a class="header-anchor" href="#旧材料的使用边界" aria-label="Permalink to &quot;旧材料的使用边界&quot;">​</a></h2><h3 id="仍然适合按原文学习" tabindex="-1">仍然适合按原文学习 <a class="header-anchor" href="#仍然适合按原文学习" aria-label="Permalink to &quot;仍然适合按原文学习&quot;">​</a></h3><ul><li>Java 基础语法、类、接口、集合、异常、IO、日期时间。</li><li>Maven 的项目结构、依赖、生命周期和常用命令。</li><li>HTTP、Servlet、请求响应、Cookie、Session 的底层概念。</li><li>Spring IoC、DI、AOP、Bean、Controller、Service、Mapper 的职责边界。</li><li>SQL 参数、事务、Mapper XML、DO/DTO/VO 的工程概念。</li></ul><h3 id="适合作为历史项目阅读材料" tabindex="-1">适合作为历史项目阅读材料 <a class="header-anchor" href="#适合作为历史项目阅读材料" aria-label="Permalink to &quot;适合作为历史项目阅读材料&quot;">​</a></h3><ul><li>JSP、传统 Servlet 页面案例。</li><li>XML 大量配置的 Spring 项目。</li><li>Hystrix、Zuul、Swagger2、FastDFS 等旧项目常见组件。</li><li>基于截图的微服务商城实战。</li></ul><p>阅读这些内容时，重点放在“它解决什么问题、边界在哪里、现在会用什么替代思路”，不要直接复制为新项目方案。</p><h3 id="新文章应补齐的标准" tabindex="-1">新文章应补齐的标准 <a class="header-anchor" href="#新文章应补齐的标准" aria-label="Permalink to &quot;新文章应补齐的标准&quot;">​</a></h3><p>每篇新整理的文章至少包含：</p><ul><li>适用场景：什么时候需要这个知识点。</li><li>最小代码：能独立运行或被项目调用。</li><li>调用链：谁调用谁，数据怎么流动。</li><li>验收命令：例如 <code>java -version</code>、<code>mvn test</code>、<code>curl</code> 请求或接口测试。</li><li>常见错误：至少一个真实报错和定位方法。</li><li>版本说明：只在影响行为时写版本，不随手写“最新版”。</li></ul><h2 id="技术词第一次出现时这样写" tabindex="-1">技术词第一次出现时这样写 <a class="header-anchor" href="#技术词第一次出现时这样写" aria-label="Permalink to &quot;技术词第一次出现时这样写&quot;">​</a></h2><p>先写能做什么，再写术语。</p><table tabindex="0"><thead><tr><th>弱写法</th><th>更适合本系列的写法</th></tr></thead><tbody><tr><td>学习 IoC 和 DI</td><td>让对象依赖由 Spring 创建和组装（IoC / DI），减少类之间自己 new 的耦合</td></tr><tr><td>学习 AOP</td><td>把日志、事务、权限这类横切逻辑从业务代码里抽出来（AOP）</td></tr><tr><td>学习 Mapper</td><td>用接口和 SQL 文件把 Java 方法映射到数据库操作（Mapper）</td></tr><tr><td>学习 DTO 和 VO</td><td>把数据库对象和接口返回对象分开，避免把表结构直接暴露给前端（DTO / VO）</td></tr></tbody></table><p>下一步：<a href="./03-学习验收清单">03-学习验收清单</a>。</p></div>',1)])])}const u=a(o,[["render",i]]);export{v as __pageData,u as default};
